// One normalized identifier namespace for reusable physical assets.
let equipmentAssets=[{id:'FREEZER-001',name:'Freezer 1',type:'Freezer'},{id:'CARRINHO-001',name:'Carrinho de sorvete 1',type:'Carrinho de sorvete'}];
function assetIdKey(id){return String(id).normalize('NFKC').trim().toUpperCase().replace(/[\s_-]+/g,'-')}
normalizeBoxCode=assetIdKey;
function assetRecords(){return [...packages.map(p=>({id:p.id,type:'Caixa preta'})),...boxes.map(b=>({id:b.id,type:'Caixa média / registro de estoque'})),...equipmentAssets]}
function uniqueStockId(prefix){let id;do{id=prefix+String(++seq).padStart(3,'0')}while(assetRecords().some(a=>assetIdKey(a.id)===assetIdKey(id)));return id}
function addAssetRecord(d){const id=assetIdKey(d.id),name=d.name.trim(),type=d.type;if(!id||!name||!['Caixa preta','Freezer','Carrinho de sorvete'].includes(type))throw Error('Preencha identificação, nome e tipo.');if(!/^[A-Z0-9]+(?:-[A-Z0-9]+)*$/.test(id))throw Error('Use letras, números, espaços ou hífens no ID.');if(assetRecords().some(a=>assetIdKey(a.id)===id))throw Error('ID já utilizado: '+id+'. Cada bem precisa de um ID único.');if(type==='Caixa preta')packages.push({id,name,location:locations[0],status:'Vazia · pronta para retorno'});else equipmentAssets.push({id,name,type});log(`Bem cadastrado: ${id} · ${type}`);return id}
function newAsset(){openForm('Cadastrar bem com ID único',input('id','ID / código QR')+input('name','Nome')+select('type','Tipo',['Caixa preta','Freezer','Carrinho de sorvete']),d=>addAssetRecord({...d,type:['Caixa preta','Freezer','Carrinho de sorvete'][+d.type]}))}
const inspectValidateReceipt=validateReceipt;validateReceipt=function(d){const items=inspectValidateReceipt(d);for(const item of items)for(const code of item.codes){const asset=assetRecords().find(a=>assetIdKey(a.id)===code);if(asset&&asset.type!=='Caixa preta')throw Error('ID '+code+' pertence a '+asset.type+'. Não pode ser recebido como caixa preta.')}return items};
const inspectRender=render;render=function(){inspectRender();if(view==='Cadastros')$('app').insertAdjacentHTML('beforeend',`<section class="panel"><div class="row"><div><h2>Bens com identificação única</h2><p>Caixas, freezers e carrinhos não compartilham IDs.</p></div><button onclick="newAsset()">＋ Cadastrar bem</button></div>${equipmentAssets.map(a=>`<div class="row"><div><strong>${esc(a.id)} · ${esc(a.name)}</strong><small>${esc(a.type)}</small></div></div>`).join('')}<p>Caixas cadastradas estão em Embalagens. A identificação permanece a mesma a cada retorno.</p></section>`)};render();
